window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7b6a0a4878c1a634"]={"versions": [{"id": "FIG-7b6a0a4878c1a634", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Metamodells im Kontext des Intrusion Detection Systems (IdsMapping / SecurityExtractTemplate). Es modelliert die strukturellen Eigenschaften und Zuordnungen von Kontextparametern für Sicherheitsereignisse (<code>SecurityEventContextProps</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong><code>SecurityEventContextProps</code></strong> (Spezialisierung von <code>Identifiable</code>):\n Zentrales Element mit Attributen:\n<ul class=\"fig-list\"><li><code>defaultReportingMode: SecurityEventReportingModeEnum [0..1]</code>\n</li><li><code>persistentStorage: Boolean [0..1]</code>\n</li><li><code>sensorInstanceId: PositiveInteger [0..1]</code>\n</li><li><code>severity: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li><strong><code>SecurityEventContextMapping</code></strong> (Spezialisierung von <code>IdsMapping</code>):\n Aggregiert über eine gerichtete Komposition die Rolle <code>+mappedSecurityEvent</code> mit Multiplizität <code>0..*</code> auf <code>SecurityEventContextProps</code>. Stereotyp: <code>«atpVariation,atpSplitable»</code>.\n</li><li><strong><code>SecurityEventContextData</code></strong>:\n Wird von <code>SecurityEventContextProps</code> über eine Komposition mit Rollenname <code>+contextData</code> und Multiplizität <code>0..1</code> eingebunden. Stereotyp: <code>«atpVariation»</code>.\n</li><li><strong><code>SecurityEventDefinition</code></strong> (Spezialisierung von <code>IdsCommonElement</code>):\n Enthält das Attribut <code>+ id: PositiveInteger [0..1]</code>. Es ist über eine gerichtete Referenz/Assoziation <code>+securityEvent</code> mit Multiplizität <code>0..1</code> von <code>SecurityEventContextProps</code> aus angebunden. Stereotyp: <code>«atpVariation»</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm bildet die Darstellung keine Laufzeitsequenzen oder dynamische Nachrichtenaustausche ab. Es legt die statische Deklaration und Beziehungsstruktur für Sicherheitsereignis-Kontexteigenschaften fest, die im Rahmen der IDS-Konfiguration ausgewertet und instantiiert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung unterliegt AUTOSAR-Variabilitäts- und Metamodellierungsregeln:</p>\n<ul class=\"fig-list\"><li>Rolle <code>mappedSecurityEvent</code>: Gekennzeichnet mit <code>«atpVariation,atpSplitable»</code>. Laut zugehörigem Tagged-Value-Kommentar gilt für den Variationspunkt: <code>atp.Status = draft</code>, <code>vh.latestBindingTime = preCompileTime</code>.\n</li><li>Rollen <code>contextData</code> und <code>securityEvent</code>: Jeweils als Variationspunkt mit <code>«atpVariation»</code> annotiert. Laut zugehörigem Tagged-Value-Kommentar gilt hier: <code>atp.Status = draft</code>, <code>vh.latestBindingTime = systemDesignTime</code>.\n</li><li>Sämtliche Attribute in <code>SecurityEventContextProps</code> und <code>SecurityEventDefinition</code> besitzen die optionale Multiplizität <code>[0..1]</code>. Die Aufteilung von Mapping- und Kontextdaten über <code>atpSplitable</code> ermöglicht eine getrennte Pflege über Teildokumente hinweg.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-94b39b1657b8de63", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Metamodells im Kontext des Intrusion Detection Systems (IdsMapping / SecurityExtractTemplate). Es modelliert die strukturellen Eigenschaften und Zuordnungen von Kontextparametern für Sicherheitsereignisse (<code>SecurityEventContextProps</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong><code>SecurityEventContextProps</code></strong> (Spezialisierung von <code>Identifiable</code>):\n Zentrales Element mit Attributen:\n<ul class=\"fig-list\"><li><code>defaultReportingMode: SecurityEventReportingModeEnum [0..1]</code>\n</li><li><code>persistentStorage: Boolean [0..1]</code>\n</li><li><code>sensorInstanceId: PositiveInteger [0..1]</code>\n</li><li><code>severity: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li><strong><code>SecurityEventContextMapping</code></strong> (Spezialisierung von <code>IdsMapping</code>):\n Aggregiert über eine gerichtete Komposition die Rolle <code>+mappedSecurityEvent</code> mit Multiplizität <code>0..*</code> auf <code>SecurityEventContextProps</code>. Stereotyp: <code>«atpVariation,atpSplitable»</code>.\n</li><li><strong><code>SecurityEventContextData</code></strong>:\n Wird von <code>SecurityEventContextProps</code> über eine Komposition mit Rollenname <code>+contextData</code> und Multiplizität <code>0..1</code> eingebunden. Stereotyp: <code>«atpVariation»</code>.\n</li><li><strong><code>SecurityEventDefinition</code></strong> (Spezialisierung von <code>IdsCommonElement</code>):\n Enthält das Attribut <code>+ id: PositiveInteger [0..1]</code>. Es ist über eine gerichtete Referenz/Assoziation <code>+securityEvent</code> mit Multiplizität <code>0..1</code> von <code>SecurityEventContextProps</code> aus angebunden. Stereotyp: <code>«atpVariation»</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm bildet die Darstellung keine Laufzeitsequenzen oder dynamische Nachrichtenaustausche ab. Es legt die statische Deklaration und Beziehungsstruktur für Sicherheitsereignis-Kontexteigenschaften fest, die im Rahmen der IDS-Konfiguration ausgewertet und instantiiert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung unterliegt AUTOSAR-Variabilitäts- und Metamodellierungsregeln:</p>\n<ul class=\"fig-list\"><li>Rolle <code>mappedSecurityEvent</code>: Gekennzeichnet mit <code>«atpVariation,atpSplitable»</code>. Laut zugehörigem Tagged-Value-Kommentar gilt für den Variationspunkt: <code>atp.Status = draft</code>, <code>vh.latestBindingTime = preCompileTime</code>.\n</li><li>Rollen <code>contextData</code> und <code>securityEvent</code>: Jeweils als Variationspunkt mit <code>«atpVariation»</code> annotiert. Laut zugehörigem Tagged-Value-Kommentar gilt hier: <code>atp.Status = draft</code>, <code>vh.latestBindingTime = systemDesignTime</code>.\n</li><li>Sämtliche Attribute in <code>SecurityEventContextProps</code> und <code>SecurityEventDefinition</code> besitzen die optionale Multiplizität <code>[0..1]</code>. Die Aufteilung von Mapping- und Kontextdaten über <code>atpSplitable</code> ermöglicht eine getrennte Pflege über Teildokumente hinweg.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2ff03747c7ee1aed", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Metamodells im Kontext des Intrusion Detection Systems (IdsMapping / SecurityExtractTemplate). Es modelliert die strukturellen Eigenschaften und Zuordnungen von Kontextparametern für Sicherheitsereignisse (<code>SecurityEventContextProps</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong><code>SecurityEventContextProps</code></strong> (Spezialisierung von <code>Identifiable</code>):\n Zentrales Element mit Attributen:\n<ul class=\"fig-list\"><li><code>defaultReportingMode: SecurityEventReportingModeEnum [0..1]</code>\n</li><li><code>persistentStorage: Boolean [0..1]</code>\n</li><li><code>sensorInstanceId: PositiveInteger [0..1]</code>\n</li><li><code>severity: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li><strong><code>SecurityEventContextMapping</code></strong> (Spezialisierung von <code>IdsMapping</code>):\n Aggregiert über eine gerichtete Komposition die Rolle <code>+mappedSecurityEvent</code> mit Multiplizität <code>0..*</code> auf <code>SecurityEventContextProps</code>. Stereotyp: <code>«atpVariation,atpSplitable»</code>.\n</li><li><strong><code>SecurityEventContextData</code></strong>:\n Wird von <code>SecurityEventContextProps</code> über eine Komposition mit Rollenname <code>+contextData</code> und Multiplizität <code>0..1</code> eingebunden. Stereotyp: <code>«atpVariation,atpSplitable»</code>.\n</li><li><strong><code>SecurityEventDefinition</code></strong> (Spezialisierung von <code>IdsCommonElement</code>):\n Enthält das Attribut <code>+ id: PositiveInteger [0..1]</code>. Es ist über eine gerichtete Referenz/Assoziation <code>+securityEvent</code> mit Multiplizität <code>0..1</code> von <code>SecurityEventContextProps</code> aus angebunden. Stereotyp: <code>«atpVariation,atpSplitable»</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm bildet die Darstellung keine Laufzeitsequenzen oder dynamische Nachrichtenaustausche ab. Es legt die statische Deklaration und Beziehungsstruktur für Sicherheitsereignis-Kontexteigenschaften fest, die im Rahmen der IDS-Konfiguration ausgewertet und instantiiert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung unterliegt AUTOSAR-Variabilitäts- und Metamodellierungsregeln:</p>\n<ul class=\"fig-list\"><li>Rolle <code>mappedSecurityEvent</code>: Gekennzeichnet mit <code>«atpVariation,atpSplitable»</code>. Laut zugehörigem Tagged-Value-Kommentar gilt für den Variationspunkt: <code>atp.Status = candidate</code>, <code>vh.latestBindingTime = preCompileTime</code>.\n</li><li>Rollen <code>contextData</code> und <code>securityEvent</code>: Jeweils als Variationspunkt mit <code>«atpVariation,atpSplitable»</code> annotiert. Laut zugehörigem Tagged-Value-Kommentar gilt hier: <code>atp.Status = candidate</code>, <code>vh.latestBindingTime = systemDesignTime</code>.\n</li><li>Sämtliche Attribute in <code>SecurityEventContextProps</code> und <code>SecurityEventDefinition</code> besitzen die optionale Multiplizität <code>[0..1]</code>. Durch die Splitbarkeit (<code>atpSplitable</code>) auf allen drei Relationen können Kontextdaten, Event-Referenzen sowie Mapping-Elemente auf Artefaktebene modular und unabhängig voneinander verteilt definiert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-7b6a0a4878c1a634", "to": "FIG-94b39b1657b8de63", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-94b39b1657b8de63", "to": "FIG-2ff03747c7ee1aed", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Stereotyp an der Komposition <code>+contextData</code>: erweitert von <code>«atpVariation»</code> auf <code>«atpVariation,atpSplitable»</code>.\n</li><li>Stereotyp an der Assoziation <code>+securityEvent</code>: erweitert von <code>«atpVariation»</code> auf <code>«atpVariation,atpSplitable»</code>.\n</li><li>Anmerkungsfeld zu Variation Point Tags von <code>contextData</code> und <code>securityEvent</code>: <code>atp.Status</code> von <code>draft</code> auf <code>candidate</code> geändert; Feldposition nach rechts verschoben.\n</li><li>Anmerkungsfeld zu Variation Point Tags von <code>mappedSecurityEvent</code>: <code>atp.Status</code> von <code>draft</code> auf <code>candidate</code> geändert; Feldposition nach unten verschoben.\n</li></ul>"}]};
